import {gifts,categories,config} from './catalog.js?v=4';
const root=document.querySelector('#quiz');
const state={step:0,answers:{},view:'quiz',expanded:false};
const stages=['budget','recipient','age','interest','detail','style'];
const budgetLabels={1:'Up to $25',2:'Up to $50',3:'Up to $100',4:'Up to $200'};
const styles={practical:'Something useful',personal:'Something personal',fun:'Something fun',wow:'A bigger surprise',any:'Surprise me'};
const escape=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pronoun=()=>state.answers.recipient==='girl'?'her':state.answers.recipient==='boy'?'him':'them';
function question(){const p=pronoun();return {
budget:{title:'First, what’s your budget?',subtitle:'A thoughtful gift can start small. Choose your maximum per gift.',choices:Object.entries(budgetLabels).map(([id,title])=>({id,title,subtitle:{1:'A little something',2:'Room for a thoughtful find',3:'Make it a special one',4:'For a bigger occasion'}[id]}))},
recipient:{title:'Who are you shopping for?',subtitle:'Follow their interests. Every gift category is open to everyone.',choices:[{id:'boy',title:'Gifts for boys',subtitle:'Boyfriend, brother, friend, or someone else'},{id:'girl',title:'Gifts for girls',subtitle:'Girlfriend, sister, friend, or someone else'},{id:'anyone',title:'Gifts for anyone',subtitle:'Let their interests lead the way'}]},
age:{title:`How old is ${p==='them'?'the recipient':p==='him'?'he':'she'}?`,subtitle:'This collection is designed for teens and adults.',choices:[{id:'13',title:'13–17',subtitle:'Teen years'},{id:'18',title:'18–24',subtitle:'College years & new beginnings'},{id:'25',title:'25+',subtitle:'A little further along'}]},
interest:{title:`What sounds most like ${p}?`,subtitle:'Pick the part of their personality you want to celebrate.',choices:[{id:'nerdy',title:'A little nerdy',subtitle:'Games, fantasy worlds, and campaigns'},{id:'outside',title:'Always outside',subtitle:'Hiking, camping, hunting, or fishing'},{id:'creative',title:'The creative type',subtitle:'Art, crafts, and music'},{id:'food',title:'Into food & drinks',subtitle:'Cooking, baking, coffee, or tea'},{id:'active',title:'Active & connected',subtitle:'Fitness, sports, and useful gadgets'},{id:'everyday',title:'Loves the little things',subtitle:'Cozy nights and meaningful keepsakes'}]},
detail:{title:state.answers.interest==='nerdy'?`What does ${p==='him'?'he':p==='her'?'she':'the recipient'} geek out about?`:state.answers.interest==='outside'?'What’s their kind of adventure?':'Let’s get a little more specific.',subtitle:'Choose their strongest interest for the closest matches.',choices:Object.entries(categories).filter(([,c])=>c.group===state.answers.interest).map(([id,c])=>({id,title:c.name,subtitle:{games:'Consoles, PCs, and one more level',books:'Favorite worlds and one more chapter',tabletop:'Characters, campaigns, and lucky rolls',outdoors:'Trails, campfires, and fresh air',hunting:'Early mornings and time in the field',art:'Drawing, crafting, and new projects',music:'Playing an instrument or loving a playlist',cooking:'Kitchen experiments and homemade treats',drinks:'A favorite daily brewing ritual',fitness:'Workouts, movement, and personal goals',tech:'A useful upgrade to the everyday setup',cozy:'Comfort and memories worth keeping'}[id]}))},
style:{title:'What kind of gift feels right?',subtitle:'We’ll use this to order your matches, while keeping their interests first.',choices:Object.entries(styles).map(([id,title])=>({id,title,subtitle:{practical:'They’ll reach for it again and again',personal:'A reminder that you know them well',fun:'An activity or a little extra joy',wow:'An upgrade for a special occasion',any:'Show me the best mix'}[id]}))}
}[stages[state.step]];}
export function recommend(answers){return gifts.filter(g=>g.category===answers.detail&&g.budget<=Number(answers.budget)&&g.minAge<=Number(answers.age)).sort((a,b)=>{const score=g=>(g.style===answers.style?10:0)+g.budget;return score(b)-score(a)||a.id.localeCompare(b.id);});}
export function answer(value){const q=question();if(state.view!=='quiz'||state.step>=stages.length||!q?.choices.some(c=>c.id===String(value)))throw new Error('That answer is not available for this question.');state.answers[stages[state.step]]=String(value);for(const stage of stages.slice(state.step+1))delete state.answers[stage];state.step++;state.expanded=false;render();return {step:state.step,answers:{...state.answers}};}
function back(){if(state.view==='catalog'){state.view='quiz';}else if(state.step>0){state.step--;for(const key of stages.slice(state.step))delete state.answers[key];}state.expanded=false;render();}
function restart(){state.step=0;state.answers={};state.view='quiz';state.expanded=false;render();}
function productLink(g){const url=new URL(g.url||'https://www.amazon.com/s');if(!g.url)url.searchParams.set('k',g.query);url.searchParams.delete('tag');if(config.affiliateTag)url.searchParams.set('tag',config.affiliateTag);return url.href;}
function card(g,index,results=false){const c=categories[g.category],matches=g.style===state.answers.style;return `<article class="gift-card"><div class="gift-card-top"><span class="category-label">${escape(c.name)}</span><span class="budget-chip">${budgetLabels[g.budget]} idea</span></div>${results?`<span class="match-label">${index===0?'FIRST PICK':matches?'MATCHES YOUR GIFT STYLE':'ALSO WORTH A LOOK'}</span>`:''}<h3>${escape(g.name)}</h3><p>${escape(g.description)}</p>${results?`<p class="match-reason">Matches ${escape(c.name.toLowerCase())}${matches?` and your preference for ${styles[g.style].toLowerCase()}`:''}.</p>`:''}<details><summary>Check before buying</summary><p>${escape(g.check)}</p></details><a class="shop-link" href="${escape(productLink(g))}" target="_blank" rel="noopener noreferrer${config.affiliateTag?' sponsored':''}">${g.url?'View on Amazon':'Find options on Amazon'}<span class="sr-only"> (opens in a new tab)</span></a></article>`;}
function render(focus=true){const results=state.step===stages.length,catalog=state.view==='catalog';document.body.classList.toggle('wide',results||catalog);document.querySelector('#step-label').textContent=catalog?'THE GIFT COLLECTION':results?'YOUR SHORTLIST':`${String(state.step+1).padStart(2,'0')} / ${['BUDGET','RECIPIENT','AGE','INTERESTS','THE DETAILS','GIFT STYLE'][state.step]}`;document.querySelector('#step-count').textContent=catalog?`${gifts.length} ideas`:results?'Quiz complete':`${state.step+1} of ${stages.length}`;document.querySelector('#progress-fill').style.width=catalog||results?'100%':`${(state.step+1)/stages.length*100}%`;document.querySelector('#back').hidden=state.step===0&&!catalog;document.querySelector('#catalog-toggle').textContent=catalog?'Return to quiz':`Browse all ${gifts.length} ideas`;
if(catalog){root.innerHTML=`<h2 tabindex="-1">Browse gift ideas</h2><p class="intro">${gifts.length} gift ideas for teens and adults. Budget bands are planning estimates; check current prices with the seller.</p>${Object.entries(categories).map(([id,c])=>`<section class="catalog-group"><h3 class="category-heading">${c.name}</h3><div class="gift-grid">${gifts.filter(g=>g.category===id).map((g,i)=>card(g,i)).join('')}</div></section>`).join('')}`;}
else if(results){const matches=recommend(state.answers);const shown=state.expanded?matches:matches.slice(0,3);root.innerHTML=`<span class="tag">A FEW GOOD GUESSES FOR ${pronoun().toUpperCase()}</span><h2 tabindex="-1">Recommended gifts</h2><div class="answer-summary"><span>${budgetLabels[state.answers.budget]}</span><span>${categories[state.answers.detail].name}</span><span>${styles[state.answers.style]}</span></div><p class="intro result-intro">${matches.length} ideas fit your selected planning budget. Actual seller prices, shipping, and availability may differ.</p><div class="gift-grid">${shown.map((g,i)=>card(g,i,true)).join('')}</div>${matches.length>3?`<button class="secondary more" data-more>${state.expanded?'Show the top 3':`See ${matches.length-3} more matching ${matches.length===4?'idea':'ideas'}`}</button>`:''}<div class="result-actions"><button class="primary" data-restart>Find a gift for someone else</button><button class="text-button" data-back>Change my answers</button></div>`;}
else{const q=question();root.innerHTML=`<h2 tabindex="-1">${q.title}</h2><p class="intro">${q.subtitle}</p><div class="choices ${q.choices.length>3?'two-columns':''}">${q.choices.map(c=>`<button class="choice" data-answer="${c.id}"><span><strong>${c.title}</strong><small>${c.subtitle}</small></span></button>`).join('')}</div>${state.step===0?'<p class="budget-note">Budget bands help narrow the ideas. They are estimates, not live product prices.</p>':''}`;}
document.querySelector('#disclosure').textContent=config.affiliateTag?'As an Amazon Associate I earn from qualifying purchases. We may earn a commission when you buy through our links.':'Links open Amazon product pages or searches, as labeled. Affiliate commissions are not currently enabled.';
if(focus){root.querySelector('h2')?.focus({preventScroll:true});document.querySelector('.quiz-panel').scrollIntoView({behavior:'instant',block:'start'});}}
root.addEventListener('click',event=>{const el=event.target.closest('[data-answer],[data-restart],[data-back],[data-more]');if(!el)return;if(el.dataset.answer!==undefined)answer(el.dataset.answer);else if(el.hasAttribute('data-restart'))restart();else if(el.hasAttribute('data-back'))back();else{state.expanded=!state.expanded;render();}});
document.querySelector('#back').addEventListener('click',back);document.querySelector('#catalog-toggle').addEventListener('click',()=>{state.view=state.view==='catalog'?'quiz':'catalog';render();});document.querySelector('#home').addEventListener('click',event=>{event.preventDefault();restart();});render(false);
// Preserve the prototype's browser tool, using the same validated action as UI buttons.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'answer_gift_quiz',description:'Choose an available answer for the current gift quiz question. Values are the data-answer IDs on visible answer buttons.',inputSchema:{type:'object',properties:{answer:{type:'string'}},required:['answer'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>answer(input.answer)})).catch(()=>{});}catch{}}

